create temporary view l30d_traffic_${grass_region_without_quote} as
select cspu_id
     ,model_id
     ,item_id
     ,shop_id
     ,is_win_day
     ,order_cnt

     ,local_date
    from srdi_mart.dws_sr_data_warehouse_tc_pb_winner_order_1d
where grass_region = ${grass_region}
and local_date between date_sub(${local_date},29) and ${local_date}
;
--sql_divide_splitter--

create temporary view win_3d_models_${grass_region_without_quote} as
select model_id
from (
    select model_id
    ,local_date
    ,max(is_win_day) is_win_day
    from l30d_traffic_${grass_region_without_quote}
    where local_date between date_sub(${local_date},2) and ${local_date}
    group by 1,2
)t
group by 1
having sum(is_win_day) = 3
;
--sql_divide_splitter--

create temporary view item_order_${grass_region_without_quote} as
SELECT item_id
    ,sum(order_cnt) item_order_l30d
    ,sum(case when is_win_day = 1 then order_cnt else 0 end) winner_order_l30d
from l30d_traffic_${grass_region_without_quote}
group by 1
;
--sql_divide_splitter--

create temporary view cspu_ado_${grass_region_without_quote} as
select cspu_id
    ,sum(order_cnt)/30 cspu_ado
from l30d_traffic_${grass_region_without_quote}
group by 1
;
--sql_divide_splitter--

create temporary view all_cspu_model_${grass_region_without_quote} as
select cspu_id
     ,model_id
     ,item_id
     ,shop_id
FROM srdi_mart.dim_sr_data_warehouse_pb_all_cspu_link_analysis_hf
WHERE grass_region = ${grass_region}
  AND local_date = ${local_date}
 and local_hour = (select max(local_hour) from srdi_mart.dim_sr_data_warehouse_pb_all_cspu_link_analysis_hf
                  WHERE grass_region = ${grass_region} AND local_date = ${local_date})
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_tc_pb_winner_item_tag_df
partition(grass_region = ${grass_region}, local_date = ${local_date})
select item_id
    ,shop_id
from (
    select a.model_id
        ,a.item_id
        ,a.shop_id
        ,coalesce(item_order_l30d,0) item_order_l30d
        ,coalesce(winner_order_l30d,0) winner_order_l30d
        ,coalesce(cspu_ado,0) cspu_ado
    from all_cspu_model_${grass_region_without_quote} a
    inner join win_3d_models_${grass_region_without_quote} b
    on a.model_id = b.model_id
    left join item_order_${grass_region_without_quote} c
    on a.item_id = c.item_id
    left join cspu_ado_${grass_region_without_quote} d
    on a.cspu_id = d.cspu_id
)t
where (case when item_order_l30d > 0 then winner_order_l30d/item_order_l30d >= 0.3
    else cspu_ado >= 5 end)
group by 1,2
;
